<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class Product extends Model {protected $fillable=['category_id','name','slug','description','image','base_price','tax_rate','is_active','is_featured','preparation_minutes']; protected $casts=['base_price'=>'decimal:2','tax_rate'=>'decimal:4','is_active'=>'boolean','is_featured'=>'boolean']; public function category(){return $this->belongsTo(Category::class);} public function branches(){return $this->belongsToMany(Branch::class)->withPivot('price','is_available');} public function options(){return $this->hasMany(ProductOption::class);} public function orderItems(){return $this->hasMany(OrderItem::class);}}